def grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

def season(month):
    if month in ('September', 'October', 'November'):
        return 'Autumn'
    elif month in ('December', 'January', 'February'):
        return 'Winter'
    elif month in ('March', 'April', 'May'):
        return 'Spring'
    else:
        return 'Summer'

